get_shopping_cart.code:
const response = await client.shoppingCart.getShoppingCart();
const settings = response.map.shopping_cart;
console.log(settings.cart_page.show_product_thumbnail, settings.cart_page.save_cart);
console.log(settings.flying_cart.enabled, settings.flying_cart.save_cart);

patch_shopping_cart.code:
const response = await client.shoppingCart.patchShoppingCart({
    shopping_cart: {cart_page: {show_product_thumbnail: true}, flying_cart: {save_cart: true}},
});
const settings = response.map.shopping_cart;
console.log(settings.cart_page.show_product_thumbnail, settings.flying_cart.save_cart);

get_shopping_cart_section.code:
const response = await client.shoppingCart.getShoppingCartSection('cart_page');
const cartPage = response.map.cart_page;
console.log(cartPage.show_product_thumbnail, cartPage.enable_clear_cart, cartPage.save_cart);
